using CheckoutPricing.Application.Checkout;
using CheckoutPricing.Domain.Customers;

namespace CheckoutPricing.UnitTests.Application;

public sealed class CheckoutTotalCalculationTests
{
    [Fact]
    public void GoldCustomerReceivesTheApprovedDiscount()
    {
        var request = new CalculatePayableTotalRequest(CustomerTier.Gold, 100.00m);

        var result = CheckoutTotalCalculator.CalculatePayableTotal(request);

        Assert.Equal(95.00m, result.PayableTotal);
    }
}

